PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX moose: <https://trivyn.io/ontologies/moose#>
SELECT ?decision ?title ?old ?oldTitle WHERE {
  ?decision moose:supersedes ?old .
  OPTIONAL { ?decision rdfs:label ?title }
  OPTIONAL { ?old rdfs:label ?oldTitle }
}
ORDER BY ?title ?oldTitle

